The program reads the whole text from standard input and checks each line against a pattern of the form `NAME <- expression;`. Lines that don't match are skipped, which covers comments, the prose, and the output template.

For each matching line, `mod` is rewritten as Python's `%`, and the expression is checked against an allow-list of tokens. Only numbers, known variable names, `+ - * / %` and parentheses get through. The expression is then evaluated against the current variable values. Any variable used before it is assigned is treated as 0.

```python
import sys
import re

def main():
    text = sys.stdin.read()
    vars_ = {}
    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;\s*$')
    token_re = re.compile(r'\s*(\d+|[A-Za-z_]\w*|[()+\-*/%])')
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith('//'):
            continue
        m = assign_re.match(s)
        if not m:
            continue
        name, expr = m.group(1), m.group(2)
        expr = re.sub(r'\bmod\b', '%', expr)
        # validate tokens
        pos = 0
        ok = True
        tokens = []
        while pos < len(expr):
            if expr[pos].isspace():
                pos += 1
                continue
            tm = token_re.match(expr, pos)
            if not tm:
                ok = False
                break
            tok = tm.group(1)
            tokens.append(tok)
            pos = tm.end()
        if not ok:
            continue
        env = {}
        for t in tokens:
            if re.match(r'[A-Za-z_]\w*$', t):
                env[t] = vars_.get(t, 0)
        try:
            val = eval(expr.replace('/', '//'), {"__builtins__": {}}, env)
        except Exception:
            continue
        vars_[name] = val
    out = []
    for v in ['a', 'b', 'c', 'd', 'TMP']:
        out.append(f"{v} ?= {vars_.get(v, 0)};")
    print(' '.join(out))

if __name__ == '__main__':
    main()
